test("migrates the four legacy problem entries into filter V2 and removes the old entries", () => {
  const filter = { minRating: 1200, showUnrated: false, minContestDate: "2026-01-01", search: "dp" };
  StorageService.saveObject(keys.Filter, filter);
  StorageService.saveObject(keys.Page, 0);
  StorageService.saveSet(keys.Tags, new Set(["dp", "math"]));
  StorageService.saveSet(keys.SolveStatus, new Set(["ATTEMPTED"]));
  const expected = { ...filter, selected: 0, tags: ["dp", "math"], solveStatus: ["ATTEMPTED"] };

  expect(StorageService.getValue(keys.FilterV2, {})).toEqual(expected);
  expect(JSON.parse(localStorage.getItem(keys.FilterV2)!)).toEqual(expected);
  expect(localStorage.getItem(keys.Filter)).toBeNull();
  expect(localStorage.getItem(keys.Page)).toBeNull();
  expect(localStorage.getItem(keys.Tags)).toBeNull();
  expect(localStorage.getItem(keys.SolveStatus)).toBeNull();
});

