test("migration and subsequent reads merge defaults identically without persisting them", () => {
  const defaults = Object.freeze({ perPage: 100, minRating: 1200, showUnrated: true, search: "default" });
  const legacy = { minRating: 0, showUnrated: false, search: "" };
  StorageService.saveObject(keys.Filter, legacy);

  const firstRead = StorageService.getObject(keys.FilterV2, defaults);
  const secondRead = StorageService.getObject(keys.FilterV2, defaults);

  expect(firstRead).toEqual({ perPage: 100, ...legacy });
  expect(secondRead).toEqual(firstRead);
  expect(JSON.parse(localStorage.getItem(keys.FilterV2)!)).toEqual(legacy);
  expect(defaults).toEqual({ perPage: 100, minRating: 1200, showUnrated: true, search: "default" });
});

